import type {ReportCell} from '@/lib/report-export';
export type RevenueRecommendationInput={stayDate:string;currentRateMinor:number;effectiveUnits:number;reservedUnits:number;minimumRateMinor:number;maximumRateMinor:number;competitorRateMinor:number|null;eventUpliftBasisPoints:number};
export type RevenueRecommendation={status:'ready';mode:'human_approval';recommendedRateMinor:number;unconstrainedRateMinor:number;adjustmentBasisPoints:number;occupancyPercent:number;guardrail:'none'|'minimum'|'maximum';explanations:string[]};
export type RevenueApproval={planId:string;expectedVersion:number;stayDate:string;recommendedRateMinor:number};
export type RevenueDecisionCommand={p_tenant:string;p_property:string;p_request:string;p_plan:string;p_expected_version:number;p_stay_date:string;p_current_rate_minor:number;p_recommended_rate_minor:number;p_minimum_rate_minor:number;p_maximum_rate_minor:number;p_competitor_rate_minor:number|null;p_event_uplift_basis_points:number;p_effective_units:number;p_reserved_units:number;p_occupancy_tenths_percent:number;p_adjustment_basis_points:number;p_guardrail:'none'|'minimum'|'maximum';p_explanations:string[]};
export type RevenueDecisionServerReceipt={request_id:string;tenant_id:string;property_id:string;plan_id:string;stay_date:string;recommended_rate_minor:number;saved_at:string;replayed:boolean};
export type RevenueDecisionAuditSummary={request_id:string;actor_id:string;plan_id:string;reviewed_plan_version:number;stay_date:string;current_rate_minor:number;recommended_rate_minor:number;minimum_rate_minor:number;maximum_rate_minor:number;competitor_rate_minor:number|null;event_uplift_basis_points:number;effective_units:number;reserved_units:number;occupancy_tenths_percent:number;adjustment_basis_points:number;guardrail:'none'|'minimum'|'maximum';saved_at:string};
export type RevenueDecisionAuditPage={tenant_id:string;property_id:string;items:RevenueDecisionAuditSummary[];next:{saved_at:string;request_id:string}|null};
const integer=(value:number,min:number,max:number)=>Number.isInteger(value)&&value>=min&&value<=max;
// All bounded products stay below Number.MAX_SAFE_INTEGER. Round rational ties toward +infinity.
const roundedRatio=(numerator:number,denominator:number)=>{const quotient=Math.floor(numerator/denominator);return quotient+((numerator-quotient*denominator)*2>=denominator?1:0)};
export function revenueRecommendation(input:RevenueRecommendationInput):RevenueRecommendation{
 if(!/^\d{4}-\d{2}-\d{2}$/.test(input.stayDate)||(!Number.isFinite(Date.parse(input.stayDate))||new Date(input.stayDate).toISOString().slice(0,10)!==input.stayDate))throw Error('Choose a valid stay night.');
 if(!integer(input.currentRateMinor,1,100000000)||!integer(input.minimumRateMinor,1,100000000)||!integer(input.maximumRateMinor,1,100000000)||input.minimumRateMinor>input.maximumRateMinor)throw Error('Enter valid rate guardrails with the minimum at or below the maximum.');
 if(!integer(input.effectiveUnits,1,100000)||!integer(input.reservedUnits,0,100000)||input.reservedUnits>input.effectiveUnits)throw Error('A complete, non-oversold capacity row is required for this preview.');
 if(input.competitorRateMinor!==null&&!integer(input.competitorRateMinor,1,100000000))throw Error('Enter a valid competitor rate or leave it blank.');
 if(!integer(input.eventUpliftBasisPoints,0,5000))throw Error('Event uplift must be from 0% to 50%.');
 const occupancyPercent=roundedRatio(input.reservedUnits*1000,input.effectiveUnits)/10,occupancyBps=input.reservedUnits*100>=input.effectiveUnits*95?2500:input.reservedUnits*100>=input.effectiveUnits*80?1500:input.reservedUnits*100>=input.effectiveUnits*60?800:input.reservedUnits*100<input.effectiveUnits*30?-1000:0,explanations=[`${input.reservedUnits} of ${input.effectiveUnits} effective rooms are reserved (${occupancyPercent.toFixed(1)}%). Occupancy contributes ${occupancyBps>=0?'+':''}${(occupancyBps/100).toFixed(2)}%.`];
 let competitorBps=0;if(input.competitorRateMinor!==null){competitorBps=Math.max(-1000,Math.min(1000,roundedRatio((input.competitorRateMinor-input.currentRateMinor)*5000,input.currentRateMinor)));explanations.push(`The entered competitor rate contributes ${competitorBps>=0?'+':''}${(competitorBps/100).toFixed(2)}%, capped at 10%.`)}else explanations.push('No competitor rate was entered; competitor impact is 0%.');
 explanations.push(`Manager-entered event uplift contributes +${(input.eventUpliftBasisPoints/100).toFixed(2)}%.`);
 const adjustment=Math.max(-3000,Math.min(5000,occupancyBps+competitorBps+input.eventUpliftBasisPoints)),unconstrained=roundedRatio(input.currentRateMinor*(10000+adjustment),10000),recommended=Math.max(input.minimumRateMinor,Math.min(input.maximumRateMinor,unconstrained)),guardrail=recommended===unconstrained?'none':recommended===input.minimumRateMinor?'minimum':'maximum';
 explanations.push(guardrail==='none'?'The calculated price is inside the entered guardrails.':`The ${guardrail} guardrail changed the calculated price.`,'This is deterministic decision support in human-approval mode. It is not an AI demand forecast. The calculation alone does not save or distribute a rate.');
 return {status:'ready',mode:'human_approval',recommendedRateMinor:recommended,unconstrainedRateMinor:unconstrained,adjustmentBasisPoints:adjustment,occupancyPercent,guardrail,explanations};
}

export function prepareRevenueApproval(reviewed:boolean,input:RevenueApproval):RevenueApproval{
 if(!reviewed)throw Error('Review every recommendation input and explanation before saving.');
 if(!/^[A-Za-z0-9_-]{1,128}$/.test(input.planId)||!integer(input.expectedVersion,1,2147483647)||!/^\d{4}-\d{2}-\d{2}$/.test(input.stayDate)||!integer(input.recommendedRateMinor,1,100000000))throw Error('The reviewed recommendation is incomplete. Refresh rates and prepare it again.');
 return {...input};
}

// This identifies a displayed review, not authorization to write a rate.
export function revenueReviewKey(scope:{actorId:string;tenantId:string;propertyId:string;currency:string;planId:string;planVersion:number;planName:string},input:RevenueRecommendationInput,result:RevenueRecommendation):string{
 return JSON.stringify([scope.actorId,scope.tenantId,scope.propertyId,scope.currency,scope.planId,scope.planVersion,scope.planName,
  input.stayDate,input.currentRateMinor,input.effectiveUnits,input.reservedUnits,input.minimumRateMinor,input.maximumRateMinor,input.competitorRateMinor,input.eventUpliftBasisPoints,
  result.status,result.mode,result.recommendedRateMinor,result.unconstrainedRateMinor,result.adjustmentBasisPoints,result.occupancyPercent,result.guardrail,result.explanations]);
}

export function prepareRevenueDecisionCommand(scope:{tenantId:string;propertyId:string;requestId:string},approval:RevenueApproval,input:RevenueRecommendationInput,result:RevenueRecommendation):RevenueDecisionCommand{
 if(![scope.tenantId,scope.propertyId,scope.requestId,approval.planId].every(uuid)||approval.expectedVersion!==inputVersion(approval.expectedVersion)||approval.stayDate!==input.stayDate||approval.recommendedRateMinor!==result.recommendedRateMinor||result.mode!=='human_approval')throw Error('The reviewed rate decision no longer matches its workspace or recommendation.');
 const canonical=revenueRecommendation(input);
 if(result.recommendedRateMinor!==canonical.recommendedRateMinor||result.adjustmentBasisPoints!==canonical.adjustmentBasisPoints||result.occupancyPercent!==canonical.occupancyPercent||result.guardrail!==canonical.guardrail)throw Error('The review calculation changed; prepare it again.');
 if(result.occupancyPercent!==roundedRatio(input.reservedUnits*1000,input.effectiveUnits)/10||result.adjustmentBasisPoints<-3000||result.adjustmentBasisPoints>5000||result.explanations.length<1||result.explanations.length>20||result.explanations.some(note=>!note||note.length>1000))throw Error('The reviewed rate decision is inconsistent.');
 return {p_tenant:scope.tenantId,p_property:scope.propertyId,p_request:scope.requestId,p_plan:approval.planId,p_expected_version:approval.expectedVersion,p_stay_date:approval.stayDate,p_current_rate_minor:input.currentRateMinor,p_recommended_rate_minor:result.recommendedRateMinor,p_minimum_rate_minor:input.minimumRateMinor,p_maximum_rate_minor:input.maximumRateMinor,p_competitor_rate_minor:input.competitorRateMinor,p_event_uplift_basis_points:input.eventUpliftBasisPoints,p_effective_units:input.effectiveUnits,p_reserved_units:input.reservedUnits,p_occupancy_tenths_percent:roundedRatio(input.reservedUnits*1000,input.effectiveUnits),p_adjustment_basis_points:result.adjustmentBasisPoints,p_guardrail:result.guardrail,p_explanations:[...result.explanations]};
}

export function readRevenueDecisionServerReceipt(value:unknown,command:RevenueDecisionCommand):RevenueDecisionServerReceipt{
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('The rate-decision server receipt is missing.');const receipt=value as RevenueDecisionServerReceipt;
 if(receipt.request_id!==command.p_request||receipt.tenant_id!==command.p_tenant||receipt.property_id!==command.p_property||receipt.plan_id!==command.p_plan||receipt.stay_date!==command.p_stay_date||receipt.recommended_rate_minor!==command.p_recommended_rate_minor||Number.isNaN(Date.parse(receipt.saved_at))||typeof receipt.replayed!=='boolean')throw Error('The rate-decision server receipt does not match the reviewed request. Keep the exact request for recovery.');return receipt;
}

export function readRevenueDecisionAuditPage(value:unknown,tenant:string,property:string):RevenueDecisionAuditPage{
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('The server rate-decision history is missing.');const page=value as RevenueDecisionAuditPage;
 if(page.tenant_id!==tenant||page.property_id!==property||!Array.isArray(page.items)||page.items.length>25)throw Error('The server rate-decision history belongs to another property.');
 const requests=new Set<string>();let prior='';for(const item of page.items){const key=item.saved_at+'/'+item.request_id;if(![item.request_id,item.actor_id,item.plan_id].every(uuid)||requests.has(item.request_id)||!integer(item.reviewed_plan_version,1,2147483647)||!/^\d{4}-\d{2}-\d{2}$/.test(item.stay_date)||![item.current_rate_minor,item.recommended_rate_minor,item.minimum_rate_minor,item.maximum_rate_minor].every(amount=>integer(amount,1,100000000))||item.minimum_rate_minor>item.maximum_rate_minor||item.recommended_rate_minor<item.minimum_rate_minor||item.recommended_rate_minor>item.maximum_rate_minor||!(item.competitor_rate_minor===null||integer(item.competitor_rate_minor,1,100000000))||!integer(item.event_uplift_basis_points,0,5000)||!integer(item.effective_units,1,100000)||!integer(item.reserved_units,0,item.effective_units)||!integer(item.occupancy_tenths_percent,0,1000)||item.occupancy_tenths_percent!==roundedRatio(item.reserved_units*1000,item.effective_units)||!integer(item.adjustment_basis_points,-3000,5000)||!['none','minimum','maximum'].includes(item.guardrail)||Number.isNaN(Date.parse(item.saved_at))||prior&&key>=prior)throw Error('The server rate-decision history contains an invalid item.');requests.add(item.request_id);prior=key}
 if(page.next!==null&&(!page.next||!uuid(page.next.request_id)||Number.isNaN(Date.parse(page.next.saved_at))))throw Error('The server rate-decision history cursor is invalid.');return page;
}

function inputVersion(value:number){return integer(value,1,2147483647)?value:0}

export type RevenueDecisionReceipt={requestId:string;tenantId:string;propertyId:string;actorId:string;propertyName:string;planId:string;planName:string;planVersion:number;stayDate:string;savedResponseAt:string;currentRateMinor:number;recommendedRateMinor:number;minimumRateMinor:number;maximumRateMinor:number;competitorRateMinor:number|null;eventUpliftBasisPoints:number;effectiveUnits:number;reservedUnits:number;occupancyPercent:number;adjustmentBasisPoints:number;guardrail:string;explanations:string[]};
const money=(minor:number)=>`${Math.floor(minor/100)}.${String(minor%100).padStart(2,'0')}`;
export function revenueDecisionReceiptRows(value:RevenueDecisionReceipt):ReportCell[][]{
 if(![value.requestId,value.tenantId,value.propertyId,value.actorId].every(uuid)||!value.propertyName||!/^[A-Za-z0-9_-]{1,128}$/.test(value.planId)||!value.planName||!integer(value.planVersion,1,2147483647)||!/^\d{4}-\d{2}-\d{2}$/.test(value.stayDate)||Number.isNaN(Date.parse(value.savedResponseAt))||![value.currentRateMinor,value.recommendedRateMinor,value.minimumRateMinor,value.maximumRateMinor].every(amount=>integer(amount,1,100000000))||!(value.competitorRateMinor===null||integer(value.competitorRateMinor,1,100000000))||!integer(value.eventUpliftBasisPoints,0,5000)||!integer(value.effectiveUnits,1,100000)||!integer(value.reservedUnits,0,value.effectiveUnits)||!Number.isFinite(value.occupancyPercent)||!integer(value.adjustmentBasisPoints,-3000,5000)||!Array.isArray(value.explanations)||value.explanations.length>20||value.explanations.some(note=>typeof note!=='string'||note.length>1000))throw Error('The rate decision receipt is incomplete.');
 return [['iRatePilot PMS','Human-reviewed rate decision receipt'],['Property',value.propertyName],['Property reference',value.propertyId],['Request reference',value.requestId],['Reviewed by',value.actorId],['Rate plan',value.planName],['Rate plan ID',value.planId],['Reviewed plan version',value.planVersion],['Stay night',value.stayDate],['Successful PMS response observed at',value.savedResponseAt],['Current rate USD',money(value.currentRateMinor)],['Saved recommended rate USD',money(value.recommendedRateMinor)],['Minimum guardrail USD',money(value.minimumRateMinor)],['Maximum guardrail USD',money(value.maximumRateMinor)],['Competitor median USD',value.competitorRateMinor===null?'Not entered':money(value.competitorRateMinor)],['Manager event uplift %',(value.eventUpliftBasisPoints/100).toFixed(2)],['Effective rooms',value.effectiveUnits],['Reserved rooms',value.reservedUnits],['Booked occupancy %',value.occupancyPercent.toFixed(1)],['Combined adjustment %',(value.adjustmentBasisPoints/100).toFixed(2)],['Guardrail applied',value.guardrail],['Mode','Human approval'],['Scope','One PMS nightly price'],['Distribution','Not verified by this receipt'],['Audit limitation','Browser-retained receipt after a successful PMS response; coordinated server-side decision audit activation remains pending.'],[],['Explanation'],...value.explanations.map(note=>[note])];
}

function uuid(value:string){return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)}
